typedef struct CodecOps {
    size_t (*encode)(const uint8_t *in, size_t n, uint8_t *out);
    size_t (*decode)(const uint8_t *in, size_t n, uint8_t *out);
} CodecOps;

typedef struct { const CodecOps *ops; void *state; } Codec;   /* Context */

static const CodecOps gzip_ops = { .encode = gz_encode, .decode = gz_decode };

static size_t codec_write(Codec c, const uint8_t *in, size_t n, uint8_t *out) {
    return c.ops->encode(in, n, out);
}
